Translate("frFR", "demetria", {
	title = "Demetria",
	subtitle = "L'Oracle écarlate",
	found = "La route entre Main de Tyr et Stratholme",
	hint = [=[Guettez sur la route au nord de Main de Tyr l'Oracle et ses gardes.]=],
	allegiance = "Croisade écarlate",
	aliases = { "L'Oracle écarlate" },
	sections = {
		{
			title = "Résumé",
			text = [=[Demetria est la principale conseillère du grand croisé de la {link:scarlet-crusade}Croisade écarlate{/link}. On l'appelle l'Oracle en raison des sens qu'on lui prête, au-delà de ceux des autres mortels. Ses conseils ont valu à la Croisade plusieurs victoires contre le {link:scourge}Fléau{/link}. Quand les {link:forsaken}Réprouvés{/link} réécrivirent les ordres de la Croisade, elle fut envoyée au nord depuis {link:tyr-s-hand}Main de Tyr{/link}, vers Stratholme, avec ses gardes, et {link:nathanos-blightcaller}Nathanos Blightcaller{/link} envoya ses chasseurs à sa rencontre sur la route.]=],
